import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] t = new long[(int) n];
        for (int i = 0; i < t.length; i++) t[i] = Long.parseLong(next());

        Deque<Long> window = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            window.addLast(t[i]);
            while (window.peekFirst() < t[i] - 3000) window.pollFirst();
            sb.append(window.size()).append(i + 1 < n ? " " : "\n");
        }
        System.out.print(sb);
    }
}
